package cli

import (
	"os"
	"sort"
	"testing"
)

// TestFloorCalibration is a throwaway probe: it embeds the live brain's decision
// summaries and prints the cosine distribution for known-positive (paraphrase)
// and known-negative (unrelated) queries so the semantic-fallback floor can be
// chosen empirically. Run with CALIB_BRAIN pointing at a built brain.
func TestFloorCalibration(t *testing.T) {
	brainDir := os.Getenv("CALIB_BRAIN")
	if brainDir == "" {
		t.Skip("set CALIB_BRAIN to a built brain dir")
	}
	e := defaultEmbedder()
	if e == nil {
		t.Fatal("no embedder")
	}
	manifest, err := loadBrainManifest(brainDir)
	if err != nil || manifest.Sources == nil || manifest.Sources.History == nil {
		t.Fatalf("manifest: %v", err)
	}
	index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
	if err != nil {
		t.Fatalf("history index: %v", err)
	}
	var recs []historyRecord
	for _, r := range index.Records {
		if r.Kind == "decision" {
			recs = append(recs, r)
		}
	}
	// Pre-embed once.
	vecs := make([][]float32, len(recs))
	for i, r := range recs {
		vecs[i] = e.Embed(r.Summary)
	}
	t.Logf("decision records: %d", len(recs))

	probe := func(label, q string) {
		qv := e.Embed(q)
		type sc struct {
			cos float64
			s   string
		}
		all := make([]sc, len(recs))
		for i := range recs {
			all[i] = sc{cosineFloat32(qv, vecs[i]), recs[i].Summary}
		}
		sort.Slice(all, func(i, j int) bool { return all[i].cos > all[j].cos })
		t.Logf("=== %s: %q ===", label, q)
		for i := 0; i < 5 && i < len(all); i++ {
			s := all[i].s
			if len(s) > 90 {
				s = s[:90]
			}
			t.Logf("  %.3f  %q", all[i].cos, s)
		}
	}

	probe("POS", "reasons we picked one embedding approach over another")
	probe("POS", "tradeoffs of shipping native binaries to many machines")
	probe("POS", "why did we abandon the pure Go constraint")
	probe("POS", "how does reconcile decide to supersede a fact")
	probe("NEG", "fake metadata")
	probe("NEG", "banana pancake breakfast recipe")
	probe("NEG", "weather forecast for tomorrow in Berlin")
}

