// Enable with ENTIRE_BRAIN_FACTS_BM25=1 (also accepts true/yes/on).
func factsBM25Enabled() bool {
	switch strings.ToLower(strings.TrimSpace(os.Getenv("ENTIRE_BRAIN_FACTS_BM25"))) {
	case "1", "true", "yes", "on":
		return true
	}
	return false
}

