9	// rrfK is the Reciprocal Rank Fusion constant. 60 is the canonical value from
10	// the original RRF paper and what hybrid-search systems (e.g. qmd) use; it
11	// damps the influence of a single retriever's top ranks so neither the lexical
12	// nor the semantic list can unilaterally dominate the fusion.
13	const rrfK = 60.0
14	
15	// semanticReranker holds the embedder and a cache of fact vectors. Fact ids are
16	// content-derived, so a vector is valid for the life of the fact: the in-memory
17	// cache makes an eval over many queries embed each fact at most once, and an
18	// optional disk store (recall/brief) carries vectors across CLI invocations.
19	type semanticReranker struct {
20		e       Embedder
21		cache   map[string][]float32
22		store   *embedStore     // nil => in-memory only (eval, tests)
23		touched map[string]bool // ids seen this run; nil unless disk-backed
24		dirty   bool            // a new vector was embedded this run
25	}
26	
27	// newSemanticReranker returns nil when no embedder is available, so callers can
28	// pass the result straight to rankFactsFused and get the pure-lexical path.
29	// This variant is in-memory only — used by eval and tests, which should not
30	// read or write a persistent cache.
31	func newSemanticReranker(e Embedder) *semanticReranker {
32		if e == nil {
33			return nil
34		}
35		return &semanticReranker{e: e, cache: map[string][]float32{}}
36	}
37	
38	// newSemanticRerankerForBranch adds a disk-backed vector cache under
39	// facts/<branch>/embeddings/ so recall and brief reuse vectors across
40	// invocations instead of re-embedding the branch each time.
41	func newSemanticRerankerForBranch(e Embedder, brainDir, branch string) *semanticReranker {
42		rr := newSemanticReranker(e)
43		if rr == nil {
44			return nil
45		}
46		rr.store = newEmbedStore(brainDir, branch, e.ID(), e.Dim())
47		rr.cache = rr.store.load()
48		rr.touched = map[string]bool{}
49		return rr
50	}
51	
52	func (s *semanticReranker) factVector(f factRecord) []float32 {
53		if s.touched != nil {
54			s.touched[f.ID] = true
55		}
56		if v, ok := s.cache[f.ID]; ok {
57			return v
58		}
59		v := s.e.Embed(f.Text)
60		s.cache[f.ID] = v
61		s.dirty = true
62		return v
63	}
64	
65	// retain marks ids as present this run for prune purposes, without forcing an
66	// embed. Callers pass the full branch fact set (before scope/status filtering)
67	// so flush keeps every still-present fact's cached vector and prunes only facts
68	// that genuinely left the branch — otherwise a scoped recall, which ranks only a
69	// subset, would prune the rest and thrash the cache on the next unscoped run.
70	func (s *semanticReranker) retain(facts []factRecord) {
71		if s == nil || s.touched == nil {
72			return
73		}
74		for _, f := range facts {
75			s.touched[f.ID] = true
76		}
77	}
78	
79	// flush persists vectors when disk-backed. It writes only the ids touched this
80	// run (embedded via factVector or marked present via retain), so facts removed
81	// or superseded since the last run are pruned from the cache on rewrite.
82	// Best-effort: a cache is never load-bearing.
83	func (s *semanticReranker) flush() error {
84		if s == nil || s.store == nil {
85			return nil
86		}
87		out := make(map[string][]float32, len(s.touched))
88		for id := range s.touched {
89			if v, ok := s.cache[id]; ok {
90				out[id] = v
91			}
92		}
93		// Rewrite when a new vector was embedded (dirty) or when the loaded cache
94		// holds vectors for facts no longer present this run (out ⊂ cache → stale
95		// entries to prune). Skipping both means the on-disk file already matches —
96		// so a pure cache-hit run with no departures does no I/O, but a removal-only
97		// run still prunes even though nothing new was embedded.
98		if !s.dirty && len(out) == len(s.cache) {
99			return nil
100		}
101		return s.store.save(out)
102	}
103	
104	// rankFactsFused ranks facts by Reciprocal Rank Fusion of a lexical list and a
105	// semantic (cosine) list. When rr is nil it is exactly rankFacts (pure
106	// lexical), so callers without an embedder are unaffected.
107	//
108	// The fusion is what attacks both measured failure modes at once:
109	//   - Reachability (the 0.667 lexical ceiling): the semantic list ranks the
110	//     *entire* active candidate set, so a relevant fact that shares no query
111	//     term still gets a rank and can surface — something no lexical weighting
112	//     can do.
113	//   - Ranking within reach: a fact strong in both lists fuses above one strong
114	//     in only one, reordering the lexically-reachable set by meaning.
115	//
116	// An empty (or whitespace-only) query keeps the lexical path's recency listing
117	// (no query vector to compare against), matching rankFacts exactly.
118	func rankFactsFused(facts []factRecord, query string, limit int, includeAll bool, rr *semanticReranker) []factRecord {
119		if rr == nil || strings.TrimSpace(query) == "" {
120			return rankFacts(facts, query, limit, includeAll)
121		}
122		if limit <= 0 {
123			limit = 10
124		}
125		type cand struct {
126			rec factRecord
127			lex int
128			cos float64
129		}
130		queryLocus := factLocus(query)
131		qvec := rr.e.Embed(query)
132		cands := make([]cand, 0, len(facts))
133		for _, f := range facts {
134			if !includeAll && f.Status != factStatusActive {
135				continue
136			}
137			score := factQueryScore(f, query)
138			if overlap := locusOverlap(queryLocus, f.Text); overlap > 0 {
139				score += overlap * factLocusBoost
140			}
141			cands = append(cands, cand{rec: f, lex: score, cos: cosineFloat32(qvec, rr.factVector(f))})
142		}
143		if len(cands) == 0 {
144			return nil
145		}
146	
147		// Lexical ranks: only facts with a positive lexical score are "retrieved"
148		// lexically, so only they contribute a lexical RRF term.
149		order := make([]int, len(cands))
150		for i := range order {
151			order[i] = i
152		}
153		sort.SliceStable(order, func(a, b int) bool {
154			ia, ib := order[a], order[b]
155			if cands[ia].lex != cands[ib].lex {
156				return cands[ia].lex > cands[ib].lex
157			}
158			return cands[ia].rec.UpdatedAt.After(cands[ib].rec.UpdatedAt)
159		})
160		fused := make([]float64, len(cands))
161		for rank, idx := range order {
162			if cands[idx].lex > 0 {
163				fused[idx] += 1.0 / (rrfK + float64(rank+1))
164			}
165		}
166	
167		// Semantic ranks: the full candidate set is ranked by cosine, so a
168		// term-disjoint but semantically-near fact still earns a rank.
169		sort.SliceStable(order, func(a, b int) bool {
170			ia, ib := order[a], order[b]
171			if cands[ia].cos != cands[ib].cos {
172				return cands[ia].cos > cands[ib].cos
173			}
174			return cands[ia].rec.UpdatedAt.After(cands[ib].rec.UpdatedAt)
175		})
176		for rank, idx := range order {
177			fused[idx] += 1.0 / (rrfK + float64(rank+1))
178		}
179	
180		for i := range order {
181			order[i] = i
182		}
183		sort.SliceStable(order, func(a, b int) bool {
184			ia, ib := order[a], order[b]
185			if fused[ia] != fused[ib] {
186				return fused[ia] > fused[ib]
187			}
188			return cands[ia].rec.UpdatedAt.After(cands[ib].rec.UpdatedAt)
189		})
190		if len(order) > limit {
191			order = order[:limit]
192		}
193		out := make([]factRecord, len(order))
194		for i, idx := range order {
195			out[i] = cands[idx].rec
196		}
197		return out
198	}
199	
200	// cosineFloat32 is the cosine similarity of two vectors. Vectors from the
201	// static embedder are already unit length, but guarding the norms keeps it
202	// correct for the zero vector (text that tokenizes to nothing, e.g.
203	// empty/whitespace-only) — which yields 0.
204	func cosineFloat32(a, b []float32) float64 {
205		if len(a) != len(b) {
206			return 0
207		}
208		var dot, na, nb float64
209		for i := range a {
210			dot += float64(a[i]) * float64(b[i])
211			na += float64(a[i]) * float64(a[i])
212			nb += float64(b[i]) * float64(b[i])
213		}
214		if na == 0 || nb == 0 {
215			return 0
216		}
217		return dot / (math.Sqrt(na) * math.Sqrt(nb))
218	}

