var repoKeyUnsafeChars = regexp.MustCompile(`[^a-zA-Z0-9._-]+`)
var repoRemoteSCPRegex = regexp.MustCompile(`^(?:[^@]+@)?([^:/]+):(.+)$`)
var knownRepoDomainSlugs = map[string]string{
