12		_ "modernc.org/sqlite"
13	)
14	
15	// doc_fts.go builds a derived FTS5 BM25 index over the doc records and ranks
16	// queries with it, mirroring history_fts.go. Rebuildable: deleting the .sqlite
17	// forces a clean rebuild, and any failure falls back to nothing (the caller skips
18	// docs). Heading + text are both indexed so a query matches either.
19	
20	const (
21		docFTSFileName        = "index-fts.sqlite"
22		docFTSSchema          = "1"
23		docFTSRelevanceCutoff = 0.30
24	)
25	
26	type scoredDocRecord struct {
27		Record docRecord
28		Score  int
29	}
30	
31	func docFTSDBPath(brainDir string) string {
32		return filepath.Join(brainDir, docDirName, docFTSFileName)
33	}
34	
35	func docFTSContent(r docRecord) string {
36		raw := r.Heading + " " + r.Text + " " + r.Path
37		return normalizeHistorySearchText(raw) + " " + strings.ToLower(raw)
38	}
39	
40	func docFTSFingerprint(index docIndex) string {
41		return index.GeneratedAt.UTC().Format(time.RFC3339Nano) + ":" + strconv.Itoa(len(index.Records))
42	}
43	
44	func openDocFTS(brainDir string, index docIndex) (*sql.DB, error) {
45		path := docFTSDBPath(brainDir)
46		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
47			return nil, err
48		}
49		db, err := sql.Open("sqlite", path)
50		if err != nil {
51			return nil, err
52		}
53		for _, pragma := range []string{"PRAGMA busy_timeout=5000;", "PRAGMA journal_mode=WAL;"} {
54			if _, err := db.Exec(pragma); err != nil {
55				db.Close()
56				return nil, err
57			}
58		}
59		if docFTSFresh(db, index) {
60			return db, nil
61		}
62		if err := buildDocFTS(db, index); err != nil {
63			db.Close()
64			return nil, err
65		}
66		return db, nil
67	}
68	
69	func docFTSFresh(db *sql.DB, index docIndex) bool {
70		rows, err := db.Query(`SELECT key, value FROM doc_fts_meta`)
71		if err != nil {
72			return false
73		}
74		defer rows.Close()
75		got := map[string]string{}
76		for rows.Next() {
77			var k, v string
78			if err := rows.Scan(&k, &v); err != nil {
79				return false
80			}
81			got[k] = v
82		}
83		return got["schema"] == docFTSSchema && got["fingerprint"] == docFTSFingerprint(index)
84	}
85	
86	func buildDocFTS(db *sql.DB, index docIndex) error {
87		tx, err := db.Begin()
88		if err != nil {
89			return err
90		}
91		defer tx.Rollback()
92		for _, stmt := range []string{
93			`DROP TABLE IF EXISTS doc_fts`,
94			`DROP TABLE IF EXISTS doc_fts_meta`,
95			`CREATE TABLE doc_fts_meta(key TEXT PRIMARY KEY, value TEXT)`,
96			`CREATE VIRTUAL TABLE doc_fts USING fts5(content, rec_order UNINDEXED, tokenize='porter unicode61')`,
97		} {
98			if _, err := tx.Exec(stmt); err != nil {
99				return fmt.Errorf("doc fts schema: %w", err)
100			}
101		}
102		ins, err := tx.Prepare(`INSERT INTO doc_fts(content, rec_order) VALUES (?, ?)`)
103		if err != nil {
104			return err
105		}
106		defer ins.Close()
107		for i, r := range index.Records {
108			if _, err := ins.Exec(docFTSContent(r), i); err != nil {
109				return fmt.Errorf("doc fts insert: %w", err)
110			}
111		}
112		for k, v := range map[string]string{"schema": docFTSSchema, "fingerprint": docFTSFingerprint(index)} {
113			if _, err := tx.Exec(`INSERT INTO doc_fts_meta(key, value) VALUES (?, ?)`, k, v); err != nil {
114				return err
115			}
116		}
117		return tx.Commit()
118	}
119	
120	// rankDocsViaFTS ranks doc chunks by BM25, trimming the weak tail at 30% of the
121	// top score (like history). ok=false on any failure or a degenerate query.
122	func rankDocsViaFTS(brainDir string, index docIndex, query string, limit int) ([]scoredDocRecord, bool) {
123		if limit <= 0 {
124			return nil, false
125		}
126		expr := historyFTSMatchExpr(query)
127		if expr == "" {
128			return nil, false
129		}
130		db, err := openDocFTS(brainDir, index)
131		if err != nil {
132			return nil, false
133		}
134		defer db.Close()
135		rows, err := db.Query(`SELECT CAST(rec_order AS INTEGER), bm25(doc_fts) FROM doc_fts WHERE doc_fts MATCH ? ORDER BY bm25(doc_fts) LIMIT ?`, expr, limit*4)
136		if err != nil {
137			return nil, false
138		}
139		defer rows.Close()
140		out := make([]scoredDocRecord, 0, limit)
141		seen := map[string]struct{}{}
142		var topScore float64
143		for rows.Next() {
144			var order int
145			var bm float64
146			if err := rows.Scan(&order, &bm); err != nil {
147				return nil, false
148			}
149			if order < 0 || order >= len(index.Records) {
150				continue
151			}
152			score := -bm
153			if topScore == 0 {
154				topScore = score
155			} else if score < docFTSRelevanceCutoff*topScore {
156				break
157			}
158			rec := index.Records[order]
159			if _, ok := seen[rec.ID]; ok {
160				continue
161			}
162			seen[rec.ID] = struct{}{}
163			out = append(out, scoredDocRecord{Record: rec, Score: int(score*1000 + 0.5)})
164			if len(out) >= limit {
165				break
166			}
167		}
168		if rows.Err() != nil {
169			return nil, false
170		}
171		return out, true
172	}

