package cli

import (
	"sort"
	"strings"
)

// retrieve.go is the unified retrieval layer behind the qmd-aligned verbs
// (search/vsearch/query). It ranks across the brain's text layers — facts,
// history, docs — and merges the per-source ranked lists with RRF. Each layer
// keeps its own best ranker; RRF fuses them by rank so their incomparable raw
// scores don't fight.

type unifiedResult struct {
	Source  string  `json:"source"` // fact | history | doc
	ID      string  `json:"id"`     // prefixed, addressable by get/multi-get
	Path    string  `json:"path,omitempty"`
	Heading string  `json:"heading,omitempty"`
	Line    int     `json:"line,omitempty"`
	Text    string  `json:"text"`
	Score   float64 `json:"score"`
}

type retrievalMode int

const (
	modeLexical retrievalMode = iota // search
	modeVector                       // vsearch
	modeHybrid                       // query
)

func embedQueryWith(e Embedder, q string) []float32 {
	if qe, ok := e.(queryEmbedder); ok {
		return qe.EmbedQuery(q)
	}
	return e.Embed(q)
}

// retrieveUnified ranks across facts + history + docs. Lexical (search) and
// hybrid (query) include all three; vector (vsearch) covers facts + docs —
// history vectors are Model2Vec noise and embedding tens of thousands of records
// per query is too slow, so they join the vector arm once Stage 1b's embedder
// lands. Missing layers are skipped, not errors.
func retrieveUnified(brainDir, branch, query string, limit int, mode retrievalMode) []unifiedResult {
	if limit <= 0 {
		limit = 10
	}
	all, _ := loadFacts(brainDir, branch)
	active := make([]factRecord, 0, len(all))
	for _, f := range all {
		if f.Status == factStatusActive {
			active = append(active, f)
		}
	}
	var e Embedder
	if mode != modeLexical {
		e = defaultEmbedder()
	}

	var lists [][]unifiedResult

	// Facts.
	if len(active) > 0 {
		switch mode {
		case modeLexical:
			lists = append(lists, factsToUnified(rankFacts(active, query, limit*2, false)))
		case modeVector:
			if e != nil {
				lists = append(lists, factsToUnified(factsVectorRanked(brainDir, branch, active, query, e, limit*2)))
			}
		case modeHybrid:
			var rr *semanticReranker
			if e != nil {
				rr = newSemanticRerankerForBranch(e, brainDir, branch)
			}
			lists = append(lists, factsToUnified(rankFactsFused(active, query, limit*2, false, rr)))
			if rr != nil {
				rr.retain(active)
				_ = rr.flush()
			}
		}
	}

	// History — BM25 (lexical / hybrid only).
	if mode != modeVector {
		if manifest, err := loadBrainManifest(brainDir); err == nil && manifest.Sources != nil && manifest.Sources.History != nil {
			if index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History); err == nil {
				if scored, ok := rankHistoryViaFTS(brainDir, index, "history", query, limit*2); ok {
					lists = append(lists, historyToUnified(scored))
				}
			}
		}
	}

	// Docs — all modes.
	if index, err := loadDocIndex(brainDir); err == nil && len(index.Records) > 0 {
		if mode == modeVector {
			if e != nil {
				lists = append(lists, docsVectorRanked(brainDir, index, query, e, limit*2))
			}
		} else if scored, ok := rankDocsViaFTS(brainDir, index, query, limit*2); ok {
			lists = append(lists, docsToUnified(scored))
		}
	}

	return rrfMergeUnified(lists, limit)
}

func factsVectorRanked(brainDir, branch string, facts []factRecord, query string, e Embedder, limit int) []factRecord {
	store := newEmbedStore(brainDir, branch, e.ID(), e.Dim())
	cache := store.load()
	dirty := false
	qv := embedQueryWith(e, query)
	type sc struct {
		i   int
		cos float64
	}
	scored := make([]sc, len(facts))
	for i, f := range facts {
		v, ok := cache[f.ID]
		if !ok {
			v = e.Embed(f.Text)
			cache[f.ID] = v
			dirty = true
		}
		scored[i] = sc{i, cosineFloat32(qv, v)}
	}
	if dirty {
		_ = store.save(cache)
	}
	sort.Slice(scored, func(a, b int) bool { return scored[a].cos > scored[b].cos })
	out := make([]factRecord, 0, min(limit, len(scored)))
	for _, s := range scored {
		out = append(out, facts[s.i])
		if len(out) >= limit {
			break
		}
	}
	return out
}

func docsVectorRanked(brainDir string, index docIndex, query string, e Embedder, limit int) []unifiedResult {
	store := newDocEmbedStore(brainDir, e.ID(), e.Dim())
	cache := store.load()
	dirty := false
	qv := embedQueryWith(e, query)
	type sc struct {
		i   int
		cos float64
	}
	scored := make([]sc, len(index.Records))
	for i, r := range index.Records {
		v, ok := cache[r.ID]
		if !ok {
			v = e.Embed(r.Text)
			cache[r.ID] = v
			dirty = true
		}
		scored[i] = sc{i, cosineFloat32(qv, v)}
	}
	if dirty {
		_ = store.save(cache)
	}
	sort.Slice(scored, func(a, b int) bool { return scored[a].cos > scored[b].cos })
	out := make([]unifiedResult, 0, min(limit, len(scored)))
	for _, s := range scored {
		out = append(out, docToUnified(index.Records[s.i]))
		if len(out) >= limit {
			break
		}
	}
	return out
}

func factsToUnified(facts []factRecord) []unifiedResult {
	// fact ids are already prefixed "fact:" (factRecordID); history likewise.
	out := make([]unifiedResult, len(facts))
	for i, f := range facts {
		out[i] = unifiedResult{Source: "fact", ID: f.ID, Path: strings.Join(f.Paths, ","), Text: f.Text}
	}
	return out
}

func historyToUnified(scored []scoredHistoryRecord) []unifiedResult {
	out := make([]unifiedResult, len(scored))
	for i, s := range scored {
		out[i] = unifiedResult{Source: "history", ID: s.Record.ID, Path: s.Record.Path, Line: s.Record.Line, Heading: s.Record.Kind, Text: s.Record.Summary}
	}
	return out
}

func docToUnified(r docRecord) unifiedResult {
	return unifiedResult{Source: "doc", ID: "doc:" + r.ID, Path: r.Path, Line: r.Line, Heading: r.Heading, Text: r.Text}
}

func docsToUnified(scored []scoredDocRecord) []unifiedResult {
	out := make([]unifiedResult, len(scored))
	for i, s := range scored {
		out[i] = docToUnified(s.Record)
	}
	return out
}

func rrfMergeUnified(lists [][]unifiedResult, limit int) []unifiedResult {
	fused := map[string]float64{}
	rec := map[string]unifiedResult{}
	for _, list := range lists {
		for rank, r := range list {
			fused[r.ID] += 1.0 / (rrfK + float64(rank+1))
			if _, ok := rec[r.ID]; !ok {
				rec[r.ID] = r
			}
		}
	}
	out := make([]unifiedResult, 0, len(rec))
	for id, r := range rec {
		r.Score = fused[id]
		out = append(out, r)
	}
	sort.Slice(out, func(a, b int) bool {
		if out[a].Score != out[b].Score {
			return out[a].Score > out[b].Score
		}
		return out[a].ID < out[b].ID
	})
	if len(out) > limit {
		out = out[:limit]
	}
	return out
}

// getUnified resolves a prefixed id (fact:/history:/doc:) to its full record.
func getUnified(brainDir, branch, id string) (unifiedResult, bool) {
	switch {
	case strings.HasPrefix(id, "fact:"):
		facts, _ := loadFacts(brainDir, branch)
		for _, f := range facts {
			if f.ID == id {
				return factsToUnified([]factRecord{f})[0], true
			}
		}
	case strings.HasPrefix(id, "history:"):
		if manifest, err := loadBrainManifest(brainDir); err == nil && manifest.Sources != nil && manifest.Sources.History != nil {
			if index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History); err == nil {
				for _, r := range index.Records {
					if r.ID == id {
						return historyToUnified([]scoredHistoryRecord{{Record: r}})[0], true
					}
				}
			}
		}
	case strings.HasPrefix(id, "doc:"):
		want := strings.TrimPrefix(id, "doc:")
		if index, err := loadDocIndex(brainDir); err == nil {
			for _, r := range index.Records {
				if r.ID == want {
					return docToUnified(r), true
				}
			}
		}
	}
	return unifiedResult{}, false
}

package cli

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// doc.go is the `doc` source: it indexes the brain's own markdown — the
// agent-synthesized seed summaries plus the copied repo docs under seed/docs/ —
// into retrievable chunks. Facts/history cover session-derived work; docs cover
// the written/designed knowledge sessions don't, and give the brain a way to
// retrieve its own documentation (qmd's core use case). The index is a derived,
// rebuildable artifact, like the history index.

const (
	docDirName        = "docs"
	docIndexFileName  = "index.json"
	docIndexPath      = docDirName + "/" + docIndexFileName
	maxDocChunkBytes  = 3000 // ~750 tokens, qmd-scale chunks
	docSummaryMaxSize = 700
)

type docSourceManifest struct {
	GeneratedAt time.Time `json:"generated_at"`
	IndexPath   string    `json:"index_path"`
	Records     int       `json:"records"`
	Files       int       `json:"files"`
	Warnings    []string  `json:"warnings,omitempty"`
}

type docIndex struct {
	GeneratedAt time.Time   `json:"generated_at"`
	Records     []docRecord `json:"records"`
}

type docRecord struct {
	ID      string `json:"id"`
	Path    string `json:"path"`    // brain-relative markdown path
	Heading string `json:"heading"` // nearest section heading, for context
	Line    int    `json:"line"`    // 1-based start line in the file
	Text    string `json:"text"`
}

func docRecordID(path string, line int, text string) string {
	sum := sha256.Sum256([]byte(fmt.Sprintf("%s\x00%d\x00%s", path, line, text)))
	return hex.EncodeToString(sum[:])[:12]
}

// firstHeading returns the first markdown heading in a chunk (without the leading
// #s), so a retrieved chunk can be labeled with its section.
func firstHeading(text string) string {
	for _, line := range strings.Split(text, "\n") {
		t := strings.TrimSpace(line)
		if strings.HasPrefix(t, "#") {
			return strings.TrimSpace(strings.TrimLeft(t, "#"))
		}
	}
	return ""
}

// loadDocRecordsFromSeed scans every markdown file under brain/seed and chunks it
// into doc records. Size-based chunking (qmd-style) keeps it simple and robust.
func loadDocRecordsFromSeed(brainDir string) ([]docRecord, int, error) {
	seedDir := filepath.Join(brainDir, seedDirName)
	if _, err := os.Stat(seedDir); err != nil {
		return nil, 0, nil // no seed yet; not an error
	}
	var records []docRecord
	files := 0
	err := filepath.WalkDir(seedDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() || !strings.HasSuffix(strings.ToLower(path), ".md") {
			return nil
		}
		data, rErr := os.ReadFile(path)
		if rErr != nil {
			return nil
		}
		rel, relErr := filepath.Rel(brainDir, path)
		if relErr != nil {
			rel = path
		}
		rel = filepath.ToSlash(rel)
		files++
		for _, c := range chunkTranscript(string(data), maxDocChunkBytes) {
			text := strings.TrimSpace(c.Text)
			if text == "" {
				continue
			}
			records = append(records, docRecord{
				ID:      docRecordID(rel, c.StartLine, text),
				Path:    rel,
				Heading: firstHeading(text),
				Line:    c.StartLine,
				Text:    text,
			})
		}
		return nil
	})
	return records, files, err
}

// writeDocIndexAndSource builds and persists the doc index + manifest source from
// the seed markdown. It mirrors writeBrainHistoryIndexAndSource.
func writeDocIndexAndSource(brainDir string, now time.Time) (*docSourceManifest, error) {
	records, files, err := loadDocRecordsFromSeed(brainDir)
	if err != nil {
		return nil, err
	}
	index := docIndex{GeneratedAt: now, Records: records}
	data, err := json.MarshalIndent(index, "", "  ")
	if err != nil {
		return nil, err
	}
	data = append(data, '\n')
	if err := writeFileAtomic(filepath.Join(brainDir, filepath.FromSlash(docIndexPath)), data, 0o600); err != nil {
		return nil, fmt.Errorf("write doc index: %w", err)
	}
	source := &docSourceManifest{GeneratedAt: now, IndexPath: docIndexPath, Records: len(records), Files: files}
	// Build the derived BM25 index alongside its truth (best-effort).
	if db, ftsErr := openDocFTS(brainDir, index); ftsErr == nil {
		_ = db.Close()
	}
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		return nil, err
	}
	if manifest.Sources == nil {
		manifest.Sources = &brainSources{}
	}
	manifest.Sources.Docs = source
	if manifest.GeneratedAt.IsZero() {
		manifest.GeneratedAt = now
	}
	if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
		return nil, err
	}
	return source, nil
}

// newDocEmbedStore is the disk-backed vector cache for doc chunks, mirroring the
// fact embed store: keyed by doc id, headered with the embedder model+dim so a
// model switch triggers a clean rebuild. This is the pure-Go stand-in for
// sqlite-vec — brute-force cosine over a cached set, fast at the brain's scale.
func newDocEmbedStore(brainDir, modelID string, dim int) *embedStore {
	dir := filepath.Join(brainDir, docDirName, embedStoreDirName)
	return &embedStore{path: filepath.Join(dir, embedStoreFileName), modelID: modelID, dim: dim}
}

func loadDocIndex(brainDir string) (docIndex, error) {
	var index docIndex
	data, err := os.ReadFile(filepath.Join(brainDir, filepath.FromSlash(docIndexPath)))
	if err != nil {
		return index, err
	}
	return index, json.Unmarshal(data, &index)
}

package cli

import "testing"

func TestUnifiedIDsNotDoublePrefixed(t *testing.T) {
	// fact/history ids are already source-prefixed; docs are not.
	f := factsToUnified([]factRecord{{ID: "fact:abc", Text: "x"}})
	if f[0].ID != "fact:abc" {
		t.Fatalf("fact id double-prefixed: %s", f[0].ID)
	}
	h := historyToUnified([]scoredHistoryRecord{{Record: historyRecord{ID: "history:def", Summary: "y"}}})
	if h[0].ID != "history:def" {
		t.Fatalf("history id double-prefixed: %s", h[0].ID)
	}
	if d := docToUnified(docRecord{ID: "ghi", Text: "z"}); d.ID != "doc:ghi" {
		t.Fatalf("doc id: %s", d.ID)
	}
}

func TestRRFMergeUnifiedFavorsCrossListMatches(t *testing.T) {
	lists := [][]unifiedResult{
		{{ID: "a"}, {ID: "b"}},
		{{ID: "b"}, {ID: "c"}},
	}
	out := rrfMergeUnified(lists, 10)
	if len(out) != 3 || out[0].ID != "b" {
		t.Fatalf("expected b (in both lists) ranked first, got %v", out)
	}
}

