import importlib.util, json, sys
spec=importlib.util.spec_from_file_location("probe","/tmp/mcp_probe.py")
probe=importlib.util.module_from_spec(spec); spec.loader.exec_module(probe)

def short(s,n=90): return " ".join(str(s).split())[:n]

def digest(name,status,payload):
    if status!="OK": return f"  {name:20} {status}: {short(payload,120)}"
    try: d=json.loads(payload)
    except: return f"  {name:20} OK text: {short(payload)}"
    def listfield(*keys):
        for k in keys:
            if isinstance(d,dict) and isinstance(d.get(k),list): return k,d[k]
        return None,None
    if name in ("brain_query","brain_search","brain_vsearch","brain_get","brain_multi_get"):
        rs=d.get("results",[]) if isinstance(d,dict) else []
        if not rs: return f"  {name:20} OK  0 results"
        lines=[f"  {name:20} OK  {len(rs)} results"]
        for r in rs[:2]:
            lines.append(f"        [{r.get('source')}] {short(r.get('path',''),28):28} {short(r.get('text',''),64)}")
        return "\n".join(lines)
    if name=="brain_stale": return f"  {name:20} OK  severity={d.get('severity')} axes={[a.get('name') if isinstance(a,dict) else a for a in (d.get('axes') or [])][:4]}"
    if name=="brain_brief":
        sem=d.get('semantic',{}); his=d.get('history',{}); fac=d.get('facts',{})
        def cnt(x): 
            if isinstance(x,dict):
                for v in x.values():
                    if isinstance(v,list): return len(v)
            return len(x) if isinstance(x,list) else '?'
        return f"  {name:20} OK  status={d.get('status')} sem_ctx={cnt(sem)} hist={cnt(his)} facts={cnt(fac)} edit_files={len(d.get('likely_edit_files',[]))}"
    if name in ("brain_context",):
        k,l=listfield("context"); l=l or []
        return f"  {name:20} OK  {len(l)} symbols; "+", ".join(short(x.get('qualified_name') or x.get('name'),30) for x in l[:3])
    if name=="brain_impact":
        k,l=listfield("impact"); l=l or []
        return f"  {name:20} OK  {len(l)} impacted; "+", ".join(short((x.get('symbol') or x).get('qualified_name','') if isinstance(x.get('symbol'),dict) else x.get('qualified_name') or x.get('name',''),30) for x in l[:3])
    if name=="brain_changes":
        k,l=listfield("changes"); l=l or []
        return f"  {name:20} OK  {len(l)} changed symbols"
    if name=="brain_code":
        rs=d.get("results",[]) if isinstance(d,dict) else []
        return f"  {name:20} OK  {len(rs)} symbols; "+", ".join(short(r.get('qualified_name') or r.get('name'),34) for r in rs[:3])
    if name=="brain_tests":
        k,l=listfield("tests"); l=l or []
        return f"  {name:20} OK  {len(l)} tests; "+", ".join(short(x.get('qualified_name') or x.get('name') or x.get('path'),34) for x in l[:3])
    if name=="brain_boundaries":
        k,l=listfield("boundary","boundaries"); l=l or []
        return f"  {name:20} OK  {len(l)} boundaries; "+", ".join(short(x.get('qualified_name') or x.get('name'),30) for x in l[:4])
    if name=="brain_regressions":
        l=d.get('anomalies') or []
        return f"  {name:20} OK  {len(l)} anomalies; scanned={d.get('scanned_files')}; warn={short(d.get('warnings'),40)}"
    if name=="brain_review":
        l=d.get('findings') or d.get('anomalies') or []
        return f"  {name:20} OK  {len(l)} findings"
    return f"  {name:20} OK  keys={list(d.keys())[:6] if isinstance(d,dict) else type(d)}"

probe.digest=digest

def go(repo,label,q,brief,symq):
    print(f"\n################## {label}  ({repo}) ##################")
