        ("brain_vsearch",{"query":q,"limit":5}),("brain_get",{"id":ids[0] if ids else "fact:none"}),
        ("brain_multi_get",{"ids":ids if ids else ["fact:none"]}),("brain_context",{"query":symq,"limit":5}),
        ("brain_impact",{"query":symq,"limit":5,"depth":1}),("brain_changes",{"limit":10}),
        ("brain_code",{"query":symq,"limit":5}),("brain_tests",{"query":symq,"limit":5}),
        ("brain_boundaries",{"kind":"tool","limit":10}),("brain_regressions",{"query":symq,"limit":5}),
        ("brain_review",{"query":symq,"limit":5})]
    res=probe.run_session(repo,calls)
    print(f"  query={q!r}  symbol-query={symq!r}  get-ids={ids}")
    for n,s,p in res: print(digest(n,s,p))

