3	import (
4		"bytes"
5		"encoding/json"
6		"net/http"
7		"os"
8		"time"
9	)
10	
11	// embed_ollama.go is the Stage 1b embedder spike: it shells the EmbeddingGemma
12	// GGUF to a local Ollama server (the plan's runner option 2 — trivial, at the
13	// cost of a running service) so the transformer embedder can be A/B'd against the
14	// Model2Vec baseline on `facts eval` before committing to the cgo llama.cpp build.
15	//
16	// Enabled with ENTIRE_BRAIN_EMBEDDER=ollama; the model defaults to
17	// "embeddinggemma" (override with ENTIRE_BRAIN_OLLAMA_MODEL). It applies
18	// EmbeddingGemma's asymmetric task prefixes — a different instruction for queries
19	// than documents — via the optional queryEmbedder interface; getting that wrong
20	// is the documented way recall degrades.
21	
22	type ollamaEmbedder struct {
23		model string
24		url   string
25		dim   int
26		hc    *http.Client
27	}
28	
29	func newOllamaEmbedder() *ollamaEmbedder {
30		model := os.Getenv("ENTIRE_BRAIN_OLLAMA_MODEL")
31		if model == "" {
32			model = "embeddinggemma"
33		}
34		// Default to Ollama's embed API; ENTIRE_BRAIN_EMBED_URL points instead at any
35		// endpoint that accepts {"model","input"} and returns {"embeddings":[[...]]}
36		// — e.g. the node-llama-cpp spike server (qmd's in-process GGUF runner).
37		url := os.Getenv("ENTIRE_BRAIN_EMBED_URL")
38		if url == "" {
39			url = "http://localhost:11434/api/embed"
40		}
41		return &ollamaEmbedder{
42			model: model,
43			url:   url,
44			hc:    &http.Client{Timeout: 60 * time.Second},
45		}
46	}
47	
48	func (o *ollamaEmbedder) ID() string { return "ollama:" + o.model }
49	
50	func (o *ollamaEmbedder) Dim() int {
51		if o.dim == 0 {
52			o.embed("title: none | text: probe")
53		}
54		return o.dim
55	}
