		}
	case "user": // claude
		message := jsonMap(obj["message"])
		if message != nil {
			return userRequestFragment(userTextFromContent(message["content"]))
		}
		return userRequestFragment(userTextFromContent(obj["content"]))
	}
	return nil
}

